package com.ecopulse.service; import com.ecopulse.dto.ConsumptionDtos; import com.ecopulse.model.Building; import com.ecopulse.model.ConsumptionRecord; import com.ecopulse.repository.BuildingRepository; import com.ecopulse.repository.ConsumptionRepository; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.*; @Service public class AnalyticsService { private final ConsumptionRepository repo; private final BuildingRepository buildings; public AnalyticsService(ConsumptionRepository r,BuildingRepository b){repo=r;buildings=b;} public List<ConsumptionRecord> records(Long org,Instant from,Instant to){return repo.findByOrganizationIdAndRecordedAtBetweenOrderByRecordedAtAsc(org,from,to);} private BigDecimal sum(List<ConsumptionRecord> rs,java.util.function.Function<ConsumptionRecord,BigDecimal> f){return rs.stream().map(f).reduce(BigDecimal.ZERO,BigDecimal::add);} public ConsumptionDtos.Summary summary(Long org,Instant from,Instant to){var rs=records(org,from,to); BigDecimal e=sum(rs,x->x.electricityKwh),w=sum(rs,x->x.waterLiters),wa=sum(rs,x->x.wasteKg),c=sum(rs,x->x.costInr),co=sum(rs,x->x.co2Kg); double score=score(e,w,wa,rs.size()); return new ConsumptionDtos.Summary(e,w,wa,c,co,score,rs.size());} private double score(BigDecimal e,BigDecimal w,BigDecimal wa,int n){if(n==0)return 0; double raw=100-(e.doubleValue()/n/20)-(w.doubleValue()/n/500)-(wa.doubleValue()/n); return Math.max(0,Math.min(100,raw));} public List<ConsumptionDtos.Point> trends(Long org,Instant from,Instant to){return records(org,from,to).stream().collect(Collectors.groupingBy(x->x.recordedAt.atZone(ZoneOffset.UTC).toLocalDate(),TreeMap::new,Collectors.toList())).entrySet().stream().map(e->new ConsumptionDtos.Point(e.getKey().toString(),sum(e.getValue(),x->x.electricityKwh),sum(e.getValue(),x->x.waterLiters),sum(e.getValue(),x->x.wasteKg),sum(e.getValue(),x->x.costInr),sum(e.getValue(),x->x.co2Kg))).toList();} public List<ConsumptionDtos.BuildingSummary> byBuilding(Long org,Instant from,Instant to){var rs=records(org,from,to); return buildings.findByOrganizationId(org).stream().map(b->{var br=rs.stream().filter(r->r.buildingId.equals(b.id)).toList(); var e=sum(br,x->x.electricityKwh); var w=sum(br,x->x.waterLiters); var wa=sum(br,x->x.wasteKg); var co=sum(br,x->x.co2Kg); return new ConsumptionDtos.BuildingSummary(b.id,b.name,b.occupancy,e,w,wa,co,score(e,w,wa,br.size()));}).toList();} public List<ConsumptionDtos.AlertView> anomalies(Long org,Instant from,Instant to){var rs=records(org,from,to); Map<Long,List<ConsumptionRecord>> grouped=rs.stream().collect(Collectors.groupingBy(x->x.buildingId)); Map<Long,Building> bm=buildings.findByOrganizationId(org).stream().collect(Collectors.toMap(x->x.id,x->x)); List<ConsumptionDtos.AlertView> out=new ArrayList<>(); grouped.forEach((id,list)->{double avg=list.stream().mapToDouble(x->x.electricityKwh.doubleValue()).average().orElse(0); list.stream().filter(x->avg>0&&x.electricityKwh.doubleValue()>avg*1.35).forEach(x->out.add(new ConsumptionDtos.AlertView(x.id,"ELECTRICITY_SPIKE","HIGH","Electricity usage is "+Math.round((x.electricityKwh.doubleValue()/avg-1)*100)+"% above this building's average.","OPEN",x.recordedAt.toString(),bm.get(id)==null?"Unknown":bm.get(id).name)));}); return out.stream().limit(20).toList();} }
